import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Verifica manuale di M23: terminale integrato e finestra separata","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m23-terminale.md","filePath":"qa/m23-terminale.md"}'),n={name:"qa/m23-terminale.md"};function d(r,e,s,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="verifica-manuale-di-m23-terminale-integrato-e-finestra-separata" tabindex="-1">Verifica manuale di M23: terminale integrato e finestra separata <a class="header-anchor" href="#verifica-manuale-di-m23-terminale-integrato-e-finestra-separata" aria-label="Permalink to &quot;Verifica manuale di M23: terminale integrato e finestra separata&quot;">​</a></h1><p>Prove a mano per ciò che le suite automatiche non vedono: shell vere, una seconda finestra del sistema, processi che non devono restare orfani, ConPTY su Windows. Il lavoro è descritto in <a href="./../roadmap.html#13-sedecies-m23--terminale-integrato-ancorabile-e-sganciabile">roadmap §13-sedecies</a> e in <a href="./../adr/0064-terminale-integrato-e-finestra-separata.html">ADR-0064</a>; la guida per gli utenti è <a href="./../user-guide/terminale.html">terminale.md</a>.</p><p><strong>Stato al 2026-11-20: nessun caso di questo runbook è stato eseguito.</strong> Nomi, tasti e comportamenti sono stati letti sul codice. La colonna «Esito» è vuota di proposito: si scrive <code>ok</code>, <code>ko</code> (con una riga sul difetto e il livello P0, P1 o P2) oppure <code>n/d</code>, con data, sistema e versione. <strong>Nulla del terminale è provato su una finestra reale, e il driver di Windows (ConPTY, Job Object) è provato solo in compilazione.</strong></p><h2 id="che-cosa-coprono-gia-le-prove-automatiche" tabindex="-1">Che cosa coprono già le prove automatiche <a class="header-anchor" href="#che-cosa-coprono-gia-le-prove-automatiche" aria-label="Permalink to &quot;Che cosa coprono già le prove automatiche&quot;">​</a></h2><p><strong>Coperto (non va ripetuto a mano, salvo dubbio):</strong></p><ul><li><strong>Core Go su macOS e Linux, con <code>/bin/sh</code> vero:</strong> <code>apps/desktop/internal/terminal/terminal_unix_test.go</code> e <code>terminal_test.go</code> (apertura, <code>cwd</code>, eco, resize, <code>Snapshot</code> e <code>seq</code>, limite di sessioni, chiusura di un tab e di tutto con verifica che il gruppo di processi non esista più, figlio in background ucciso, <code>Shutdown</code> entro 3 s), <code>ring_test.go</code>, <code>internal/app/bindings_terminal_test.go</code> (<code>terminal-read-only</code>, <code>CanOpen</code>, chiusura delle sessioni di un vault che diventa di sola lettura), <code>internal/shell/terminal_window_test.go</code> (finestra separata), <code>apps/desktop/terminal_window_test.go</code> (<code>/terminal.html</code> con la stessa CSP), <code>internal/sync/manager_mounts_test.go</code> (<code>TestReadOnlyHookFiresWhenAMountBecomesReadOnly</code>).</li><li><strong>Frontend:</strong> vitest in <code>packages/workbench/src/terminal/</code> (<code>model</code>, <code>dock</code>, <code>keys</code>, <code>controller</code>, <code>commands</code>, <code>TerminalPanel</code>), <code>commands/hotkeys.test.ts</code> (<code>combosFromEvent</code>, tasto a sinistra del <code>1</code>), <code>shell/Ribbon.test.tsx</code>; Playwright sul mock dei binding: <code>apps/desktop/frontend/e2e/terminal.spec.ts</code> (<code>task e2e</code>); sul web il pulsante non c&#39;è.</li><li><strong>Compilazione:</strong> <code>task vet-windows</code> (ConPTY e Job Object), <code>task vet-linux</code>, vet per <code>GOOS=js</code> (stub), <code>task parity</code> (voce <code>terminal</code>, eccezione sul workbench).</li></ul><p><strong>Non coperto (è lo scopo di questo runbook):</strong> shell reali su ognuno dei tre sistemi; i codici fisici dei tasti su una tastiera ISO di un Mac vero; il rendering con il font vero (<code>MesloLGS NF</code>) su una finestra reale; ConPTY e Job Object a runtime; la seconda finestra del sistema (fuoco, chiusura, eventi doppi); <code>top</code> che continua dopo lo sgancio; l&#39;assenza di processi orfani su un sistema vero; i tasti su layout reali (americano e italiano); throughput con output massivo.</p><h2 id="_0-preparazione" tabindex="-1">0. Preparazione <a class="header-anchor" href="#_0-preparazione" aria-label="Permalink to &quot;0. Preparazione&quot;">​</a></h2><ul><li>Un build del client di M23 (la sezione <em>Unreleased</em> del <a href="https://github.com/E2BRAdvisory/Clarae/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>): <code>task run-desktop</code> su macOS con il vault demo, oppure il pacchetto per Windows o Linux. Non serve un cloud, salvo per T11 (vault in sola lettura) e T12 (vault privato).</li><li>Due vault locali, <code>A</code> e <code>B</code>, in cartelle diverse (di cui annotare il percorso). Per T11: un cloud con due utenti e una condivisione (stack con <code>task stack-up</code>, <code>task dev-cloud</code>); l&#39;utente di prova riceve un mount come <strong>lettore</strong>. Per T12: un vault privato (E2EE) del cloud.</li><li>Il sistema deve avere <code>ps</code> (macOS, Linux) oppure Task Manager o <code>Get-Process</code> (Windows). Su Linux <code>pstree -p</code> aiuta.</li><li>Annotare per ogni passaggio: sistema, versione dell&#39;app, layout di tastiera.</li></ul><h2 id="_1-shell-cartella-di-partenza-e-tab-t1-t6" tabindex="-1">1. Shell, cartella di partenza e tab (T1…T6) <a class="header-anchor" href="#_1-shell-cartella-di-partenza-e-tab-t1-t6" aria-label="Permalink to &quot;1. Shell, cartella di partenza e tab (T1…T6)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T1</td><td>Apertura e shell</td><td>Aprire il vault <code>A</code>. Premere il pulsante del terminale nel ribbon (sopra <em>Impostazioni</em>).</td><td>Il pannello compare <strong>in basso</strong>, con una scheda. <strong>macOS e Linux:</strong> <code>echo $SHELL; echo $0; pwd</code> mostra la shell di login e la <strong>radice di <code>A</code></strong>. <strong>Windows:</strong> <code>$PSVersionTable.PSVersion</code> e <code>pwd</code> (PowerShell 7 se c&#39;è <code>pwsh.exe</code>, altrimenti <code>powershell.exe</code>, altrimenti <code>cmd.exe</code>: <code>echo %cd%</code>); cartella = radice di <code>A</code>. Il pulsante risulta premuto.</td><td></td></tr><tr><td>T2</td><td>Ambiente</td><td>Nella shell: <code>echo $TERM $COLORTERM $TERM_PROGRAM</code> (Windows: <code>$env:TERM</code>, <code>$env:COLORTERM</code>, <code>$env:TERM_PROGRAM</code>). Poi <code>ls --color</code> (o <code>Get-ChildItem</code>), <code>vim</code>/<code>nano</code> e <code>top</code> (macOS e Linux).</td><td><code>xterm-256color truecolor Clarae</code>. I colori si vedono, i programmi a schermo intero funzionano, il ridimensionamento del pannello adatta le righe (provare a trascinare il divisore).</td><td></td></tr><tr><td>T3</td><td>Cambio vault</td><td>Con il terminale aperto, passare al vault <code>B</code> (selettore dei vault). Aprire una <strong>nuova</strong> scheda con <code>+</code>. Tornare alla scheda vecchia.</td><td>La scheda vecchia è ancora viva e nella radice di <code>A</code>. La nuova parte nella radice di <code>B</code>. Il terminale non si chiude cambiando vault.</td><td></td></tr><tr><td>T4</td><td>Senza vault</td><td>Chiudere tutti i vault (o avviare senza un vault aperto), se l&#39;app lo permette, e aprire il terminale.</td><td>La shell parte nella cartella <strong>home</strong> dell&#39;utente. Se l&#39;app non permette di restare senza vault, segnare <code>n/d</code>.</td><td></td></tr><tr><td>T5</td><td>Tab</td><td>Aprire tre schede con <code>+</code>; usare le frecce sinistra e destra sulle schede; <code>Canc</code> su una; <code>×</code> su un&#39;altra; chiudere l&#39;ultima.</td><td>Ogni scheda ha la sua shell (provare <code>export X=1</code> in una: le altre non lo vedono). Il titolo mostra la cartella e, poi, quello che la shell imposta. Chiudere l&#39;<strong>ultima</strong> scheda chiude il pannello. Un nuovo apri riparte da zero.</td><td></td></tr><tr><td>T6</td><td>Posizioni e dimensione</td><td>Scegliere dal selettore <strong>A sinistra</strong>, <strong>A destra</strong>, <strong>In basso</strong>; trascinare il divisore; chiudere e riavviare l&#39;app.</td><td>Il pannello si sposta e si ridimensiona; <strong>posizione e dimensione restano al riavvio</strong> (<code>localStorage</code>, chiave <code>clarae.terminal.dock</code>, per dispositivo). Lo schermo del terminale si adatta senza barre di scorrimento spurie.</td><td></td></tr></tbody></table><h2 id="_2-finestra-separata-t7-t9" tabindex="-1">2. Finestra separata (T7…T9) <a class="header-anchor" href="#_2-finestra-separata-t7-t9" aria-label="Permalink to &quot;2. Finestra separata (T7…T9)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T7</td><td>Sgancio con <code>top</code></td><td>In una scheda lanciare <code>top</code> (macOS e Linux) o un ciclo come <code>while ($true) { Get-Date; Start-Sleep 1 }</code> (Windows); in un&#39;altra scrivere un testo lungo. Premere <strong>Sgancia terminale</strong> (all&#39;estrema destra della barra).</td><td>Si apre <strong>una finestra del sistema</strong> «Clarae notanda — Terminale» con le <strong>stesse schede</strong>; il pannello sparisce dalla finestra principale. <code>top</code> <strong>non si è fermato né riavviato</strong> (il contatore e il tempo continuano), il testo dell&#39;altra scheda c&#39;è, con la cronologia di scorrimento.</td><td></td></tr><tr><td>T8</td><td>Riaggancio</td><td>Nella finestra separata premere <strong>Aggancia a Clarae</strong>.</td><td>La finestra si chiude, il pannello torna nella principale con le schede e l&#39;output, <code>top</code> <strong>ancora vivo</strong> (stesso PID: <code>ps</code> prima e dopo).</td><td></td></tr><tr><td>T9</td><td>Finestra separata: uso</td><td>Sganciare di nuovo. Con <code>+</code> aprire una scheda nella finestra separata (il vault della scheda in primo piano); scrivere in entrambe le finestre; provare la finestra principale e quella separata affiancate.</td><td>La nuova scheda parte nella radice del vault della <strong>scheda in primo piano</strong>. Solo la finestra separata disegna e prende i tasti; la principale non mostra il pannello. Il fuoco passa correttamente da una finestra all&#39;altra (annotare differenze per sistema: Windows e Linux possono dare il fuoco alla principale in modo diverso quando la separata si chiude).</td><td></td></tr></tbody></table><h2 id="_3-chiusure-senza-processi-orfani-t10-e-seguenti" tabindex="-1">3. Chiusure senza processi orfani (T10 e seguenti) <a class="header-anchor" href="#_3-chiusure-senza-processi-orfani-t10-e-seguenti" aria-label="Permalink to &quot;3. Chiusure senza processi orfani (T10 e seguenti)&quot;">​</a></h2><p>Per ogni caso: <strong>prima</strong> lanciare in una scheda <code>sleep 1000 &amp;</code> e <code>nohup sleep 1001 &amp;</code> (macOS e Linux) o <code>Start-Process notepad</code> e <code>ping -t 127.0.0.1</code> (Windows), e annotare i PID con <code>ps -axo pid,ppid,pgid,sess,command | grep sleep</code> (macOS), <code>ps -eo pid,ppid,pgid,sid,cmd | grep sleep</code> (Linux) o Task Manager.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T10a</td><td>Chiusura di un tab</td><td>Premere <code>×</code> sulla scheda che ha avviato i processi. Ripetere <code>ps</code> dopo un paio di secondi.</td><td>La scheda si chiude e <strong>la shell e i suoi figli non esistono più</strong>, compreso <code>nohup sleep</code> (nessun orfano, anche quelli che ignorano il segnale di chiusura). Le altre schede sono intatte.</td><td></td></tr><tr><td>T10b</td><td><code>exit</code> dalla shell</td><td>In una scheda: <code>exit</code> (codice 0). In un&#39;altra: <code>exit 3</code>.</td><td>Con <code>exit</code> la scheda <strong>si chiude</strong>. Con <code>exit 3</code> la scheda <strong>resta</strong> con l&#39;avviso «La shell è terminata (codice di uscita 3)» finché non la si chiude.</td><td></td></tr><tr><td>T10c</td><td>Chiusura della finestra separata</td><td>Sganciare, lanciare i processi, <strong>chiudere la finestra con il pulsante del sistema</strong>.</td><td><strong>Tutte</strong> le shell terminano, senza conferma; i processi non esistono più; il pannello torna nella principale <strong>chiuso</strong>; l&#39;app principale resta aperta e utilizzabile.</td><td></td></tr><tr><td>T10d</td><td>Aggancia non uccide</td><td>Sganciare, lanciare <code>sleep 1000</code>, premere <strong>Aggancia a Clarae</strong>, controllare <code>ps</code>.</td><td><code>sleep</code> è <strong>ancora vivo</strong> (stesso PID). Poi chiudere la scheda: sparisce.</td><td></td></tr><tr><td>T10e</td><td>Chiusura della principale con la finestra separata aperta</td><td>Sganciare, lanciare i processi, chiudere la finestra <strong>principale</strong> (conferma del salvataggio, se chiesta).</td><td>Si chiude anche la finestra del terminale e <strong>nessun processo resta</strong>. L&#39;app non rimane viva con una finestra sola.</td><td></td></tr><tr><td>T10f</td><td>Uscita dell&#39;app</td><td>Con il terminale agganciato e processi in esecuzione, uscire (<code>Cmd+Q</code>, <code>Alt+F4</code> o dal menu).</td><td>L&#39;app esce <strong>entro circa 3 secondi</strong> e <code>ps</code>/Task Manager non mostrano processi della sessione. Provare anche con <code>trap &#39;&#39; HUP</code> in una shell (macOS e Linux): viene ucciso comunque.</td><td></td></tr><tr><td>T10g</td><td>Arresto anomalo (Windows)</td><td>Con processi avviati dal terminale, terminare l&#39;app dal Task Manager (<em>Termina attività</em>).</td><td><strong>Windows:</strong> il Job Object (<code>KILL_ON_JOB_CLOSE</code>) fa terminare i processi figli. Su macOS e Linux non c&#39;è un&#39;equivalenza garantita: annotare cosa succede (può restare qualcosa) senza segnare <code>ko</code>.</td><td></td></tr><tr><td>T10h</td><td>Limite di 16 sessioni</td><td>Aprire 16 schede, poi provare la 17ª.</td><td>La 17ª non parte e compare un avviso «Troppi terminali aperti» (<code>terminal-limit</code>); chiudendo una scheda si può riaprire.</td><td></td></tr></tbody></table><h2 id="_4-sola-lettura-e-vault-privati-t11-t12" tabindex="-1">4. Sola lettura e vault privati (T11, T12) <a class="header-anchor" href="#_4-sola-lettura-e-vault-privati-t11-t12" aria-label="Permalink to &quot;4. Sola lettura e vault privati (T11, T12)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T11a</td><td>Mount di sola lettura</td><td>Aprire un mount ricevuto come <strong>lettore</strong>. Guardare il pulsante nel ribbon e provare <code>+</code> e le scorciatoie.</td><td>Il pulsante e <code>+</code> sono <strong>disabilitati</strong>, con il suggerimento «questo vault è in sola lettura per te»; le scorciatoie non fanno nulla. Tornando a un vault scrivibile il pulsante si riattiva.</td><td></td></tr><tr><td>T11b</td><td>Diventa di sola lettura</td><td>Aprire un terminale in un mount da <strong>editor</strong>; il proprietario abbassa la condivisione a lettore (o la revoca).</td><td>Entro il successivo aggiornamento del mount la scheda <strong>si chiude</strong> (o resta con «Il vault è diventato di sola lettura: sessione chiusa») e il processo non esiste più. Il pulsante si disabilita.</td><td></td></tr><tr><td>T11c</td><td>Limite noto (mount chiuso)</td><td>Aprire una shell in un mount da editor, <strong>passare a un altro vault</strong>, poi abbassare la condivisione. Controllare se la shell è ancora viva.</td><td><strong>Limite noto:</strong> la shell <strong>resta viva</strong> (il mount chiuso non chiude le sessioni). Annotare il comportamento; non è un difetto nuovo ma una limitazione dichiarata.</td><td></td></tr><tr><td>T11d</td><td>Fuori dalle regole</td><td>In un vault scrivibile, dalla shell: <code>cd</code> nella cartella di un altro vault e <code>touch prova.txt</code>.</td><td><strong>Riesce</strong> (dichiarato: il terminale non è un confine di sicurezza). La guida lo dice.</td><td></td></tr><tr><td>T12</td><td>Vault privato bloccato</td><td>Aprire un terminale in un vault privato e lanciare <code>top</code> o <code>sleep 1000</code>. Bloccare il vault (manualmente o con il blocco automatico). Guardare la scheda, poi sbloccare.</td><td>La scheda è <strong>coperta</strong> («Questo vault è bloccato…») e non prende tasti; <strong>il processo resta vivo</strong> (<code>ps</code>). La copertura dipende dallo stato «bloccato» del vault, non dalla fase della sincronizzazione: mettere la sincronizzazione <strong>in pausa</strong> (o offline) a vault bloccato e verificare che la scheda resti coperta. Dopo lo sblocco l&#39;output è di nuovo visibile. Premere tasti nel terminale ritarda il blocco automatico.</td><td></td></tr></tbody></table><h2 id="_5-scorciatoie-t13-t15" tabindex="-1">5. Scorciatoie (T13…T15) <a class="header-anchor" href="#_5-scorciatoie-t13-t15" aria-label="Permalink to &quot;5. Scorciatoie (T13…T15)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T13</td><td>Layout americano</td><td>Con tastiera <strong>US</strong>: <code>Ctrl+` </code> (su macOS: <strong><code>Ctrl</code></strong>, non <code>Cmd</code>) apre e nasconde il pannello; <code>Ctrl+Maiusc+` </code> apre una scheda nuova; <code>Cmd+` </code> su macOS <strong>non</strong> fa nulla dell&#39;app (resta al sistema).</td><td>Il terminale risponde ai due tasti su macOS, Windows e Linux. Con il terminale in primo piano gli stessi tasti funzionano; <code>Ctrl+C</code>, <code>Ctrl+R</code>, <code>Ctrl+P</code> vanno alla shell.</td><td></td></tr><tr><td>T14</td><td>Layout italiano</td><td>Con tastiera <strong>italiana</strong> (macOS, Windows, Linux): premere <code>Ctrl</code> e il tasto a sinistra del <code>1</code> (scrive <code>\\</code>), <strong>fuori dal terminale</strong> (fuoco su una nota), con una <strong>nota aperta</strong> e senza. Poi con il <strong>fuoco dentro il terminale</strong> premere <code>Ctrl</code> e lo stesso tasto.</td><td><strong>macOS:</strong> apre il terminale (<code>Ctrl</code>, non <code>Cmd</code>; nessun conflitto). <strong>Windows e Linux, fuoco sulla nota:</strong> con una nota aperta esegue <strong><em>Dividi a destra</em></strong> (<code>pane:split-right</code>, <code>Mod+\\</code>) e <strong>non</strong> il terminale — <strong>conflitto noto</strong>; senza nota aperta (il comando è disabilitato) il tasto apre il terminale (alias di posizione <code>Backquote</code>). <strong>Windows e Linux, fuoco dentro il terminale:</strong> <code>Ctrl+\\</code> <strong>resta alla shell</strong> (non divide l&#39;editor e non chiude il terminale). Impostazioni › Scorciatoie <strong>non lo segnala</strong>. Annotare anche <code>Ctrl+Maiusc</code> con quel tasto.</td><td></td></tr><tr><td>T14b</td><td>Mac con tastiera ISO</td><td>Su un <strong>Mac con tastiera ISO</strong> (italiana, tedesca…): provare <code>Ctrl+` </code> con il <strong>tasto in alto a sinistra</strong> (a sinistra del <code>1</code>) e poi con il tasto <strong><code>&lt;&gt;</code></strong> accanto a Maiusc sinistro. Provare anche <code>Cmd+` </code>.</td><td><strong>Entrambi i tasti</strong> aprono e nascondono il terminale (macOS riporta il tasto in alto a sinistra come <code>IntlBackslash</code> e <code>&lt;&gt;</code> come <code>Backquote</code>: l&#39;app li accetta tutti e due; annotare se un evento arriva con un codice diverso). <code>Cmd+` </code> <strong>resta al sistema</strong> (cambia finestra dell&#39;app) e non apre il terminale. Su una tastiera ANSI (US) vale solo il tasto a sinistra del <code>1</code>.</td><td></td></tr><tr><td>T15</td><td>Copia e incolla; tasti dell&#39;app</td><td>Selezionare del testo nell&#39;output e copiare: macOS <code>Cmd+C</code> / <code>Cmd+V</code>; Windows e Linux <code>Ctrl+Maiusc+C</code> / <code>Ctrl+Maiusc+V</code>. Poi <code>Mod+Maiusc+P</code> (palette) con il fuoco nel terminale; <code>Ctrl+P</code> e <code>Ctrl+R</code> nella shell.</td><td>Copia e incolla funzionano (anche un incolla di migliaia di righe). <code>Mod+Maiusc+P</code> apre la palette dell&#39;app; <code>Ctrl+P</code> e <code>Ctrl+R</code> restano della shell (storia dei comandi). Un clic su un link <code>http</code> nell&#39;output apre il browser di sistema.</td><td></td></tr></tbody></table><h2 id="_6-prestazioni-e-uso-intenso-t16" tabindex="-1">6. Prestazioni e uso intenso (T16) <a class="header-anchor" href="#_6-prestazioni-e-uso-intenso-t16" aria-label="Permalink to &quot;6. Prestazioni e uso intenso (T16)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T16</td><td>Output massivo</td><td><code>yes | head -n 2000000</code>, <code>cat</code> di un file da 50 MB, poi <code>yes</code> e <code>Ctrl+C</code>; provare in una scheda e, in parallelo, scrivere in un&#39;altra.</td><td>L&#39;interfaccia <strong>non si blocca</strong>; <code>Ctrl+C</code> ferma <code>yes</code>; la memoria dell&#39;app non cresce senza fine. Lo sgancio dopo l&#39;output massivo ridisegna da uno snapshot (al massimo 2 MiB per sessione). Annotare i tempi.</td><td></td></tr></tbody></table><h2 id="_7-collegamenti-finestra-separata-e-uscita-immediata-t17-t19" tabindex="-1">7. Collegamenti, finestra separata e uscita immediata (T17…T19) <a class="header-anchor" href="#_7-collegamenti-finestra-separata-e-uscita-immediata-t17-t19" aria-label="Permalink to &quot;7. Collegamenti, finestra separata e uscita immediata (T17…T19)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T17</td><td>Collegamenti e OSC 8</td><td>Nella shell: <code>echo https://example.com</code>; <code>printf &#39;\\e]8;;https://example.com\\e\\\\testo\\e]8;;\\e\\\\\\n&#39;</code> (macOS e Linux; su Windows un equivalente PowerShell); poi un OSC 8 con <code>file:///etc/hosts</code> o <code>javascript:alert(1)</code>. Cliccare ogni collegamento.</td><td>I due indirizzi <code>https</code> si aprono <strong>nel browser di sistema</strong> (mai in una finestra dell&#39;app, mai con una conferma del web view). L&#39;OSC 8 con <code>file:</code> o <code>javascript:</code> <strong>non</strong> si apre.</td><td></td></tr><tr><td>T18</td><td>Finestra separata: tasti e titolo</td><td>Sganciare. Con il fuoco nella finestra separata premere le scorciatoie del terminale, anche dopo averle <strong>riassegnate</strong> in Impostazioni › Scorciatoie del vault della scheda in primo piano; sganciare con una scheda aperta in un vault diverso dall&#39;attivo. Guardare il titolo con la lingua dell&#39;app in italiano e in inglese.</td><td>Valgono le scorciatoie del vault della <strong>scheda in primo piano</strong> (le predefinite se è nella home). Il titolo è «Clarae notanda — Terminale» (inglese: «Clarae notanda — Terminal»), non quello fisso del core.</td><td></td></tr><tr><td>T19</td><td>Shell che esce subito</td><td>Su Unix, con <code>SHELL</code> che punta a uno script che esce subito (<code>#!/bin/sh</code> e <code>exit 0</code>, poi <code>exit 3</code>), aprire un terminale dalla ribbon e con <code>+</code>.</td><td>Con uscita 0 la scheda <strong>non resta</strong> come fantasma; con <code>exit 3</code> la scheda resta <strong>segnata come terminata</strong> (codice 3), senza input.</td><td></td></tr></tbody></table><h2 id="_8-carattere-e-dimensione-del-terminale-t20-t27-m24" tabindex="-1">8. Carattere e dimensione del terminale (T20…T27, M24) <a class="header-anchor" href="#_8-carattere-e-dimensione-del-terminale-t20-t27-m24" aria-label="Permalink to &quot;8. Carattere e dimensione del terminale (T20…T27, M24)&quot;">​</a></h2><p>Prova con il font vero su una finestra reale: i test automatici non misurano il rendering. Preparazione: scaricare <a href="https://github.com/romkatv/powerlevel10k-media" target="_blank" rel="noreferrer">MesloLGS NF</a> (i quattro file <code>.ttf</code>) e installarlo sul computer <strong>dopo</strong> il caso T20a; un prompt con icone (Powerlevel10k, o <code>echo -e &#39;\\ue0b0 \\uf07c \\uf121&#39;</code>) rende visibile la differenza.</p><table tabindex="0"><thead><tr><th>N.</th><th>Caso</th><th>Passi</th><th>Esito atteso</th><th>Esito</th></tr></thead><tbody><tr><td>T20a</td><td><code>MesloLGS NF</code> <strong>non</strong> installato</td><td>Prima di installarlo: Impostazioni › Aspetto, il campo «Carattere del terminale» (suggerimento <code>MesloLGS NF</code>). Aprire un terminale e stampare le icone.</td><td>Il terminale usa il <strong>ripiego</strong> (<code>ui-monospace</code>, <code>Menlo</code>, <code>Consolas</code>, <code>DejaVu Sans Mono</code>): testo leggibile a spaziatura fissa, icone come quadratini o caratteri di ripiego, nessun errore e nessun testo sovrapposto.</td><td></td></tr><tr><td>T20b</td><td><code>MesloLGS NF</code> installato</td><td>Installare il font, riavviare l&#39;app (o cambiare il campo e rimetterlo), aprire un terminale.</td><td>Le icone si vedono, le celle sono allineate (nessuna spaziatura irregolare né testo tagliato), <code>ls</code>, <code>top</code> e un editor a schermo intero riempiono la finestra.</td><td></td></tr><tr><td>T21</td><td>Cambio con un terminale aperto</td><td>Con due schede aperte (una con <code>top</code>), cambiare il campo in un altro nome installato (<code>Fira Code</code>, <code>Menlo</code>, <code>Consolas</code>) e poi in un nome <strong>non</strong> installato; infine svuotarlo.</td><td>Entrambe le schede cambiano carattere <strong>subito</strong>, senza riavviare le shell (<code>top</code> continua); un nome non installato dà il ripiego; il campo vuoto torna a <code>MesloLGS NF</code>. Un valore come <code>A, B; {x}</code> si riduce a un solo nome.</td><td></td></tr><tr><td>T22</td><td>Ridimensionamento dopo il cambio</td><td>In una scheda con <code>top</code> (o <code>stty size</code> ripetuto con <code>watch -n1 stty size</code>) cambiare il carattere con uno di dimensione diversa.</td><td>Dopo il cambio lo schermo si misura di nuovo e <strong>il numero di colonne e righe visto dalla shell cambia</strong> (<code>stty size</code>, o <code>top</code> ridisegnato); nessuna riga tagliata o barra di scorrimento spuria; vale anche per una scheda nascosta quando torna in primo piano.</td><td></td></tr><tr><td>T23</td><td>Finestra separata e più vault</td><td>Sganciare il terminale; con due vault che hanno un carattere diverso in <code>appearance.json</code>, passare da una scheda all&#39;altra della finestra separata. Cambiare il carattere dal vault della scheda in primo piano.</td><td>La finestra separata usa il carattere del vault della <strong>scheda in primo piano</strong>. Riagganciando, la finestra principale usa quello del suo vault aperto. Su una finestra di Windows e Linux annotare anche la misura delle celle subito dopo l&#39;apertura (il font può caricarsi in ritardo).</td><td></td></tr><tr><td>T24</td><td>Dimensione: cambio live</td><td>Con due schede aperte (una con <code>top</code>), in Impostazioni › Aspetto portare «Dimensione del carattere del terminale» da 13 a 20 e poi a 9.</td><td>Entrambe le schede cambiano dimensione <strong>subito</strong>, senza riavviare le shell; le celle sono allineate (nessun testo tagliato). Con la dimensione maggiore i caratteri sono più grandi e le colonne di <code>top</code> diminuiscono.</td><td></td></tr><tr><td>T25</td><td>Dimensione: PTY ridimensionato</td><td>Con <code>watch -n1 stty size</code> (o <code>top</code>) in una scheda visibile, cambiare la dimensione da 13 a 24 e poi a 10; ripetere con la scheda <strong>nascosta</strong> e poi riportata in primo piano.</td><td>Dopo il cambio e il caricamento del carattere <strong>colonne e righe viste dalla shell cambiano</strong> (più grandi → meno colonne; più piccoli → più colonne); nessuna riga tagliata, nessuna barra di scorrimento spuria; il valore corretto compare anche per la scheda nascosta quando torna in primo piano.</td><td></td></tr><tr><td>T26</td><td>Dimensione: intervallo</td><td>Scrivere nel campo <code>3</code>, <code>99</code>, <code>13.6</code>, <code>abc</code> e svuotarlo; poi (con <code>appearance.json</code> chiuso) editare il file a mano con <code>&quot;terminalFontSize&quot;: 4</code> e riaprire il vault.</td><td>Il campo non accetta valori fuori da <strong>8-32</strong> (resta nell&#39;intervallo); un valore non valido o fuori intervallo diventa <strong>13</strong> e un decimale si <strong>arrotonda</strong> (13.6 → 14). Anche al caricamento di un file con <code>4</code>, il terminale usa 13.</td><td></td></tr><tr><td>T27</td><td>Dimensione: finestra separata e web</td><td>Sganciare con due vault con dimensioni diverse in <code>appearance.json</code>; passare da una scheda all&#39;altra; una scheda nella home (senza vault). Aprire poi Impostazioni › Aspetto nel <strong>workbench web</strong>.</td><td>La finestra separata usa carattere e dimensione del vault della <strong>scheda in primo piano</strong>; per una scheda in home vale 13 e <code>MesloLGS NF</code>. Nel <strong>workbench web</strong> i campi «Carattere del terminale» e «Dimensione del carattere del terminale» <strong>non compaiono</strong>.</td><td></td></tr></tbody></table><h2 id="dopo-la-prova" tabindex="-1">Dopo la prova <a class="header-anchor" href="#dopo-la-prova" aria-label="Permalink to &quot;Dopo la prova&quot;">​</a></h2><ul><li>Compilare la colonna «Esito» e riportare i difetti P0 e P1 prima del rilascio. Un esito <code>ko</code> su T10 (processi orfani) è P0.</li><li>Se T14 mostra un comportamento diverso dal conflitto noto, aggiornare <a href="./../adr/0064-terminale-integrato-e-finestra-separata.html">ADR-0064</a> e la <a href="./../user-guide/terminale.html">guida</a>.</li><li>Su Windows riportare anche la shell trovata (pwsh, powershell o cmd) e la versione di Windows: ConPTY richiede Windows 10 1809 o successivo.</li></ul>',29)])])}const h=t(n,[["render",d]]);export{m as __pageData,h as default};
